        if (!problems.length) { zone.innerHTML = '<div class="empty-state">No authored ' + (mode === 'test' ? 'Test Mode' : 'Practice') + ' questions are available for this lesson yet.</div>'; return; }
        zone.innerHTML = '<section class="instructor-preview-intro compact"><div><span class="role-pill">' + (mode === 'test' ? 'Test Mode preview' : 'Practice preview') + '</span><p>' + (mode === 'test' ? 'A short, non-recorded test set. Work each question, then check the official answer and steps.' : 'The same authored practice material students see. This does not affect any account.') + '</p></div></section><div class="practice-preview-list">' + problems.slice(0, limit).map(function (problem, index) { return '<article class="practice-preview-problem"><div class="preview-question-head"><span class="panel-chip">Question ' + (index + 1) + '</span><span class="role-pill">' + esc(problem.difficulty || mode) + '</span></div><div class="preview-prompt">' + esc(problem.prompt || '') + '</div><label class="preview-answer-label">Your answer<input data-practice-answer="' + esc(lesson.id) + '-' + mode + '-' + index + '" placeholder="Work it out, then check" autocomplete="off"></label><div class="preview-actions"><button class="btn primary small" data-reveal-practice="' + esc(lesson.id) + '-' + mode + '-' + index + '">Check answer and steps</button></div><section class="instructor-solution" data-practice-solution="' + esc(lesson.id) + '-' + mode + '-' + index + '" hidden><strong>Official answer</strong><div class="solution-answer">' + esc(problem.correct_answer || '') + '</div><strong>Worked steps</strong><ol>' + (problem.solution_steps || []).map(function (step) { return '<li>' + esc(step) + '</li>'; }).join('') + '</ol></section></article>'; }).join('') + '</div>';
