        panel.querySelectorAll('[data-review-difficulty]').forEach(function (button) { button.onclick = function () { selected = button.dataset.reviewDifficulty; panel.querySelectorAll('[data-review-difficulty]').forEach(function (item) { item.classList.toggle('on', item === button); }); }; });
        panel.querySelectorAll('[data-review-mode]').forEach(function (button) { button.onclick = function () { var zone = panel.querySelector('.review-mode-slot'); if (button.dataset.reviewMode === 'learn') { renderGeneratedPreview(lesson, zone, selected); } else { renderStaticPreview(lesson, zone, button.dataset.reviewMode); } }; });
