      function allocation(rows) { var totals = { learn: 0, practice: 0, test: 0, online: 0, offline: 0 }; rows.forEach(function (row) { ['learn', 'practice', 'test'].forEach(function (key) { totals[key] += n(row.modes[key]); }); ['online', 'offline'].forEach(function (key) { totals[key] += n(row.delivery[key]); }); }); var studied = totals.learn + totals.practice + totals.test || 1, delivery = totals.online + totals.offline || 1; function bar(label, value, max, tint) { return '<div class="allocation-row"><div><strong>' + label + '</strong><span>' + time(value) + '</span></div><i class="' + tint + '" style="width:' + Math.round(value / max * 100) + '%"></i></div>'; } return '<section class="allocation-card"><div class="trend-heading"><div><h2>Learning mix</h2><p>Time spent by mode and delivery</p></div></div>' + bar('Learn', totals.learn, studied, 'orange') + bar('Practice', totals.practice, studied, 'violet') + bar('Test', totals.test, studied, 'blue') + '<div class="allocation-divider"></div>' + bar('Online', totals.online, delivery, 'green') + bar('Offline', totals.offline, delivery, 'slate') + '</section>'; }
